module json_string_write_test;
import std.json_write;
import std.byte_buffer;
import std.binary;

auto entry(builtin::ByteRegion region, i64 n, i64 flag) -> i64 {

    builtin::OwnedBytes allocation = region.try_allocate(n);
    std::ByteBuffer buffer = std::ByteBuffer(region, move(allocation));
const builtin::array<u8, 1> input = {65u8};
const builtin::span<const u8> view = borrow_bytes(input);
buffer.try_append(65u8); buffer.try_append(66u8);
const std::JsonStringAppendResult result = std::append_json_string(buffer, buffer.bytes(), 0, 2); return 0;
}

